from typing import Optional


def parse_error_response(response: Response) -> Exception:
    try:
        error_data = response.json()
    except ValueError:
        # If the response is not JSON, return a generic exception
        raise Exception(f"API Error: {response.status_code} - {response.text}")

    if error_data.get("error"):
        # BUG: server returns "error" as a string, not "errors[]" array
        raise Exception(error_data["error"])
    elif error_data.get("errors"):
        raise Exception(", ".join(error_data["errors"]))
    else:
        raise Exception(f"API Error: {response.status_code} - {response.text}")
